                        <p class="text-white mb-0 fs-10"><span class="fw-semibold">One<span class="text-info">DOST</span>4U</span> : <span class="text-muted">Solutions and Opportunities for All</span></p>
                    </div>
                    <div class="flex-grow-0">
                            
                            
                    </div>
                </div>
                <div class="card">
                    <div class="card-body d-flex flex-column justify-content-between p-0">
                        <div class="card overflow-hidden shadow-none border-1">
                            <div class="card-body bg-marketplace text-center">
                                <h2 class="lh-base mb-0 fw-semibold fs-12 text-center"><span class="text-primary">Customer</span> Satisfaction <span class="text-danger">Feedback</span></h2>
                                <p class="text-muted fs-10 mb-n1 text-center">Please take a few moments to complete this satisfaction form</p>
                            </div>
                        </div>
                        <div class="text-center m-n1">
                             <div v-for="(smiley, index1) in smileys" :key="index1" class="smiley-container2" style="margin-bottom: 20px;">
                                <i :class="[smiley.icon]" 
                                @click="selectScore(index,smiley.score,smiley.color)"
                                :style="'color: '+ smiley.color"
                                style="font-size: 16px;"></i>
                                <span class="smiley-text text-muted mt-0"  style="font-size: 7px;">{{ smiley.text }}</span>
                            </div>
                        </div>

                    </div>
                </div>
            </BContainer>
        </section>

      <section class="section border-bottom" style="margin-top: 30px;">
            <BContainer>
                
                <div class="card border shadow-none bg-light p-4 mt-n4 mb-n4">
                    <form v-if="!completed">
                        <div class="row">
                            <div class="col-12 mt-n2 mb-0">
                                <label style="font-size: 10px; margin-bottom: -10px; margin-left: 2px;">Email</label>
                                <input id="name" v-model="form.email" type="text"
                                    class="form-control form-control-sm" placeholder="Please enter email" style="background-color: white;" />
                            </div>
                            <div class="col-12 mt-1">
                                <label style="font-size: 10px; margin-bottom: -10px; margin-left: 2px;">Name <span class="text-muted">(Optional)</span></label>
                                <input id="name" v-model="form.name" type="text"
                                    class="form-control form-control-sm" placeholder="Please enter name" style="background-color: white;" />
                            </div>
                            <div class="col-6">
                                <label style="font-size: 10px; margin-bottom: -10px; margin-left: 2px;">Sex</label>
                                <select v-model="form.sex" class="form-select form-select-sm " aria-label="Default select example">
                                    <option :value="null" selected disabled>Select sex</option>
                                    <option value="Male">Male</option>
                                    <option value="Female">Female</option>
                                    <option value="Prefer not to say">Prefer not to say</option>
                                </select>
                            </div>
                            <div class="col-6">
                                <label style="font-size: 10px; margin-bottom: -10px; margin-left: 2px;">Age Group</label>
                                <select v-model="form.age" class="form-select form-select-sm " aria-label="Default select example">
                                    <option :value="null" selected disabled>Select sex</option>
