                            </div>
                        </div>
                    </div>
                </div>
            </BContainer>
        </section>

         <section class="section" id="plans" style="margin-top: -30px;" v-if="!completed">
            <BContainer>
                <BCol lg="12">
                <div class="modal-body p-0 text-center">
                  
                    
                    <div class="border rounded no-border mb-3">
                        <ul class="list-group list-group-flush">
                            <li class="list-group-item" :class="(list.rating) ? 'bg-dark-subtle' : ''" v-for="(list,index) in questions" v-bind:key="index" style="cursor: pointer;">
                                <div class="text-center">
                                    <p class="fs-10 text-primary fw-semibold">{{list.question}}</p>
                                    <div v-for="(smiley, index1) in smileys" :key="index1" class="smiley-container">
                                        <i :class="[smiley.icon]" 
                                        @click="selectScore(index,smiley.score,smiley.color)"
                                        :style="(list.color === smiley.color) ? 'color: '+ smiley.color : 'color: #777777'"
                                        style="font-size: 20px;"></i>
                                        <!-- <span class="smiley-text text-muted mt-0"  style="font-size: 8px;">{{ smiley.text }}</span> -->
                                    </div>
                                </div>
                            </li>
                        </ul>
                    </div>

                    <div v-if="incomplete" class="alert alert-danger border-0 mb-xl-0 fs-10 mt-2 text-center" role="alert">
                        Please rate all <b>questions</b> before submitting.
                    </div>
                    <textarea 
                    class="form-control" 
                    v-model="form.comment" 
                    id="exampleFormControlTextarea5" 
                    placeholder="Comments, complaints or suggestions" 
                    rows="2" 
                    style="font-size: 10px;"
                   :class="{ 'is-invalid': validationErrors && validationErrors.comment }"
                    ></textarea>
                    <button type="button" @click="submit" class="btn btn-primary btn-sm mt-3 mb-2" :disabled="sub">Submit</button>
                    
                </div>
               
            </BCol>
            </BContainer>
         </section>

        

        
        <BButton variant="danger" @click="topFunction" class="btn-icon" id="back-to-top">
            <i class="ri-arrow-up-line"></i>
        </BButton>
    </div>
    
    <loading v-model:active="isLoading" background-color="black" :can-cancel="false" :is-full-page="fullPage">
        <div class="text-center">
            <img src="@/assets/images/logo-sm.png" class="heartbeat-spin" style="width: 40px; height: auto;" alt="loading..." />
            <br /><br /><span class="text-white fw-semibold fs-10">Good things take time…</span>
        </div>
    </loading>
</template>

<script>
import axios from 'axios';
import { Capacitor } from '@capacitor/core';
import Loading from 'vue-loading-overlay';
import Lottie from "@/components/widgets/lottie.vue";
import animationData5 from "@/components/widgets/tqywkdcz.json";
export default {
    layout: null,
    data() {
        return {
            form:{
                email: null,
                name: null,
                sex: null,
                age: null,
                comment: null,
            },
            questions: [],
            smileys: [
                { icon: 'bx bxs-happy-beaming', active: false, score: 5, color: '#ee9f03', text: 'Strongly +'},
                { icon: 'bx bxs-smile', active: false, score: 4, color: '#feea1a', text: 'Agree' },
                { icon: 'bx bxs-meh', active: false, score: 3, color: '#5cfd9b', text: 'Neutral' },
                { icon: 'bx bxs-sad', active: false, score: 2, color: '#ff8f01', text: 'Disagree' },
                { icon: 'bx bxs-angry', active: false, score: 1, color: '#dd0000', text: 'Strongly -' }
            ],
            isIos: Capacitor.getPlatform() === 'ios',
            selectScore(index,rate,color,) {
                this.questions[index].rating = rate;
                this.questions[index].color = color;
            },
            defaultOptions5: {
                animationData: animationData5
            },
            error: null,
            incomplete: false,
            validationErrors: null,
            isLoading: false,
            completed: false,
            sub: false
        };
    },
    components: { Loading, lottie: Lottie },
    methods: {
        topFunction() {
            document.body.scrollTop = 0;
            document.documentElement.scrollTop = 0;
        },
        scrollToSection(sectionId) {
            const element = document.getElementById(sectionId);
            if (element) element.scrollIntoView({ behavior: 'smooth' });
        },
        async submit() {
            this.sub = true;
            this.isLoading = true;
            const incomplete = this.questions.filter(q => !q.rating);
            if (incomplete.length > 0) {
                this.incomplete = true;
                this.isLoading = false;
                this.sub = false;
                return;
            }
            await axios.post('/csf/public',{
                questions: this.questions,
                email: this.form.email,
                name: this.form.name,
                age: this.form.age,
                sex: this.form.sex,
                comment: this.form.comment,
            }).then(response => {
                if (response.data.status) {
                    this.$emit('success',response.data.data);
                    this.form = {
                        email: null,
                        name: null,
                        sex: null,
                        age: null,
                        comment: null,
                    };
                } 
                this.isLoading = false;
                this.sub = false;
                this.completed = true;
            }).catch(({response})=>{
                if(response.status===422){
                    this.validationErrors = response.data.errors || {};
                }else{
                    this.validationErrors = {};
                    this.error = response.data.message;
                }
                this.isLoading = false;
                this.sub = false;
            }).finally(()=>{
                this.processing = false
            });
        },
        async fetchQuestions() {
            try {
                const { data } = await axios.get('/csf/questions');
                return data;
            } catch (error) {
                console.error('Error fetching CSF questions:', error.response || error);
                throw error;
            }
        },
    },
    unmounted() {
        window.removeEventListener('scroll', this.setActiveSection);
    },
    mounted() {
        window.addEventListener('scroll', this.setActiveSection);
        let backtoTop = document.getElementById("back-to-top");
        if (backtoTop) {
            window.onscroll = function () {
                if (document.body.scrollTop > 100 || document.documentElement.scrollTop > 100) {
                    backtoTop.style.display = "block";
                } else {
                    backtoTop.style.display = "none";
                }
            };
        }
        window.addEventListener('scroll', function (ev) {
            ev.preventDefault();
            var navbar = document.getElementById("navbar");
            if (navbar) {
                if (document.body.scrollTop >= 50 || document.documentElement.scrollTop >= 50) {
                    navbar.classList.add("is-sticky");
                } else {
                    navbar.classList.remove("is-sticky");
                }
            }
        });
        this.fetchQuestions()
        .then(data => {
            this.questions = data.data;
        })
        .catch(err => {
            console.error('Failed to load CSF questions:', err);
        })
        .finally(() => {
            this.isLoading = false;
        });
    },
};
</script>

